function render(filter=''){
 const q=String(filter||'').trim().toLowerCase();
 const visible=tools.filter(([id,icon,name,desc])=>!q||(id+' '+name+' '+desc).toLowerCase().includes(q));
 library.innerHTML=visible.length?visible.map(([id,icon,name,desc])=>'<button type="button" class="tool-choice" data-tool="'+id+'"><div class="tool-art">'+icon+'</div><h3>'+name+'</h3><p>'+desc+'</p><span class="pill">Open →</span></button>').join(''):'<div class="empty">No tools match that search. Try “hash”, “encrypt” or “QR”.</div>';
 const count=document.querySelector('#toolCount');if(count)count.textContent=visible.length+' of '+tools.length+' tools';
 library.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));
}
function head(t){const x=tools.find(a=>a[0]===t);document.querySelector('#toolTitle').textContent=x[2];document.querySelector('#toolDesc').textContent=x[3];library.querySelectorAll('.tool-choice').forEach(b=>b.classList.toggle('active',b.dataset.tool===t))}
const panel=x=>{stage.innerHTML='<div class="tool-panel">'+x+'</div>'};
function openTool(name){closeWorkspace();cleanupTool();head(name);const info=tools.find(x=>x[0]===name)||tools[0];const renderers={calc,qr,scan,code,counter,json,convert,color,uuid,timer,stopwatch,game,base64,hash,encrypt,markdown,timestamp,password,regex,gradient,csv,url,jwt,diff,baseconv,colorpick,aspect,lorem,filehash,hmac,passphrase,ip,entities,contrast,shadow,clamp,slug,jsoncsv,og,sitemap,robots,mdtable,cssvars,urlparse,datecalc};renderers[name]();openWorkspace(stage,{title:info[2],description:info[3],onClose:cleanupTool})}
function evaluateExpression(source){
 let i=0;
 const skip=()=>{while(i<source.length&&/\s/.test(source[i]))i++};
 const number=()=>{skip();const start=i;while(i<source.length&&/[0-9.]/.test(source[i]))i++;const raw=source.slice(start,i);if(!raw||raw==='.'||((raw.match(/\./g)||[]).length>1))throw Error('Invalid number');const n=Number(raw);if(!Number.isFinite(n))throw Error('Invalid number');return n};
 let expression;
 const primary=()=>{skip();if(source[i]==='('){i++;const v=expression();skip();if(source[i]!==')')throw Error('Missing closing parenthesis');i++;return v}if(source[i]==='+'){i++;return primary()}if(source[i]==='-'){i++;return -primary()}return number()};
 const term=()=>{let v=primary();while(true){skip();const op=source[i];if(!['*','/','%'].includes(op))break;i++;const r=primary();if((op==='/'||op==='%')&&r===0)throw Error('Cannot divide by zero');v=op==='*'?v*r:op==='/'?v/r:v%r}return v};
 expression=()=>{let v=term();while(true){skip();const op=source[i];if(op!=='+'&&op!=='-')break;i++;const r=term();v=op==='+'?v+r:v-r}return v};
 if(!String(source).trim())throw Error('Enter an expression');const result=expression();skip();if(i!==source.length||!Number.isFinite(result))throw Error('Invalid expression');return result;
}
function calc(){panel('<input id="calcInput" class="tool-input" inputmode="decimal" aria-label="Math expression" placeholder="Example: (25*4)/2+10"><div id="calcResult" class="result-box" aria-live="polite">0</div><div class="tool-actions"><button class="btn btn-primary" id="calcBtn">Calculate</button><button class="btn btn-ghost" id="calcClear">Clear</button></div><p class="muted">Supports +, −, ×, ÷, %, decimals and parentheses. Expressions are evaluated safely without running JavaScript.</p>');const run=()=>{const out=document.querySelector('#calcResult');try{out.textContent=String(evaluateExpression(document.querySelector('#calcInput').value))}catch(e){out.textContent=e.message||'Invalid expression'}};document.querySelector('#calcBtn').onclick=run;document.querySelector('#calcInput').addEventListener('keydown',e=>{if(e.key==='Enter')run()});document.querySelector('#calcClear').onclick=()=>{document.querySelector('#calcInput').value='';document.querySelector('#calcResult').textContent='0'}}
async function qr(){panel('<p class="muted">Generate a real QR code. The QR engine loads on demand; your text is not sent to JMBHUB.</p><input id="qrText" class="tool-input" maxlength="2500" aria-label="QR text or URL" placeholder="https://example.com"><div class="qr-box"><canvas id="qrCanvas" width="240" height="240" aria-label="Generated QR code"></canvas></div><div class="tool-actions"><button class="btn btn-primary" id="qrBtn">Generate QR</button><button class="btn btn-ghost" id="qrDownload" disabled>Download PNG</button></div><div id="qrStatus" class="muted" role="status">Enter text and generate a QR code.</div>');const c=document.querySelector('#qrCanvas'),ctx=c.getContext('2d'),status=document.querySelector('#qrStatus');document.querySelector('#qrBtn').onclick=async()=>{const v=document.querySelector('#qrText').value.trim();if(!v){status.textContent='Enter some text or a URL first.';return}if(v.length>2500){status.textContent='This QR tool supports up to 2,500 characters.';return}const btn=document.querySelector('#qrBtn');btn.disabled=true;status.textContent='Generating QR…';try{const mod=await import('https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/+esm');const make=mod.default||mod;const code=make(0,'M');code.addData(v);code.make();const count=code.getModuleCount(),quiet=4,scale=Math.max(4,Math.floor(480/(count+quiet*2))),side=(count+quiet*2)*scale;c.width=c.height=side;ctx.fillStyle='#fff';ctx.fillRect(0,0,side,side);ctx.fillStyle='#111';for(let y=0;y<count;y++)for(let x=0;x<count;x++)if(code.isDark(y,x))ctx.fillRect((x+quiet)*scale,(y+quiet)*scale,scale,scale);document.querySelector('#qrDownload').disabled=false;status.textContent='QR code generated successfully.'}catch(e){status.textContent='QR engine unavailable. Check your connection and try again.'}finally{btn.disabled=false}};document.querySelector('#qrDownload').onclick=()=>{const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='jmbhub-qr.png';a.click()}}
async function scan(){panel('<p class="muted">Camera stays on your device. Some browsers need HTTPS and may not support QR detection.</p><video id="qrVideo" class="tool-video" playsinline muted></video><div id="scanResult" class="result-box" aria-live="polite">Camera off</div><button class="btn btn-primary" id="scanBtn">Start Scanner</button>');const v=document.querySelector('#qrVideo'),out=document.querySelector('#scanResult'),btn=document.querySelector('#scanBtn');let stream=null,raf=0,running=false;const stop=()=>{running=false;if(raf)cancelAnimationFrame(raf);raf=0;stream?.getTracks().forEach(t=>t.stop());stream=null;v.srcObject=null;btn.textContent='Start Scanner'};activeToolCleanup=stop;btn.onclick=async()=>{if(running){stop();out.textContent='Camera off';return}try{if(!('BarcodeDetector'in window))throw Error('QR scanning is not supported by this browser. Try a Chromium-based browser with camera access.');if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera access is not available. Open this page over HTTPS.');const detector=new BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});v.srcObject=stream;await v.play();running=true;btn.textContent='Stop Scanner';out.textContent='Scanning…';const loop=async()=>{if(!running)return;try{const found=await detector.detect(v);if(found[0]){out.textContent=found[0].rawValue;stop();return}}catch{}if(running)raf=requestAnimationFrame(loop)};loop()}catch(e){stop();out.textContent=e?.message||'Camera could not start.'}}}
function code(){panel('<textarea id="codeInput" class="tool-area" placeholder="<h1>Hello JMB</h1>"></textarea><iframe id="codeFrame" class="code-frame" sandbox="allow-scripts"></iframe><button class="btn btn-primary" id="codeRun">Run Code</button>');document.querySelector('#codeRun').onclick=()=>{document.querySelector('#codeFrame').srcdoc=document.querySelector('#codeInput').value}}
function counter(){panel('<textarea id="countText" class="tool-area" placeholder="Type or paste text here..."></textarea><div class="grid grid-3"><div class="result-box"><span>Characters: <b id="chars">0</b></span></div><div class="result-box"><span>Words: <b id="words">0</b></span></div><div class="result-box"><span>Lines: <b id="lines">0</b></span></div></div>');document.querySelector('#countText').oninput=e=>{const t=e.target.value;document.querySelector('#chars').textContent=t.length;document.querySelector('#words').textContent=t.trim()?t.trim().split(/\s+/).length:0;document.querySelector('#lines').textContent=t? t.split(/\n/).length:0}}
function json(){panel('<textarea id="jsonInput" class="tool-area" placeholder="{&quot;name&quot;:&quot;JMB&quot;}"></textarea><textarea id="jsonOutput" class="tool-area" readonly placeholder="Formatted JSON"></textarea><button class="btn btn-primary" id="jsonBtn">Format JSON</button>');document.querySelector('#jsonBtn').onclick=()=>{try{document.querySelector('#jsonOutput').value=JSON.stringify(JSON.parse(document.querySelector('#jsonInput').value),null,2)}catch{document.querySelector('#jsonOutput').value='Invalid JSON'}}}
function convert(){
 panel('<div class="form-grid"><div class="field"><label for="cv">Value</label><input id="cv" type="number" step="any" class="tool-input" value="1"></div><div class="field"><label for="ct">Conversion</label><select id="ct" class="tool-input"><option value="kmmi">Kilometres → Miles</option><option value="mikm">Miles → Kilometres</option><option value="kg">Kilograms → Pounds</option><option value="lb">Pounds → Kilograms</option><option value="cf">Celsius → Fahrenheit</option><option value="fc">Fahrenheit → Celsius</option></select></div></div><div id="cvout" class="result-box" aria-live="polite">1</div><button class="btn btn-primary" id="cvbtn">Convert</button>');
 $('#cvbtn').onclick=()=>{const input=$('#cv').value.trim(),v=Number(input),t=$('#ct').value,out=$('#cvout');if(input===''||!Number.isFinite(v)){out.textContent='Enter a valid finite number.';return}const m={kmmi:n=>n*.621371,mikm:n=>n*1.609344,kg:n=>n*2.2046226218,lb:n=>n*.45359237,cf:n=>n*9/5+32,fc:n=>(n-32)*5/9};const result=m[t](v);out.textContent=Number.isFinite(result)?String(Number(result.toFixed(6))):'Result is outside the supported numeric range.'};
}
function color(){
 panel('<div class="form-grid"><div class="field"><label for="hex">HEX</label><input id="hex" class="tool-input" value="#7c5cff" maxlength="7"></div><div class="field"><label for="rgb">RGB</label><input id="rgb" class="tool-input" readonly></div></div><div id="colorPreview" class="result-box" style="height:130px;justify-content:center">Color preview</div><div id="colorStatus" class="muted" role="status"></div><button class="btn btn-primary" id="colorBtn">Convert</button>');
 $('#colorBtn').onclick=()=>{const raw=$('#hex').value.trim().replace(/^#/,'');if(!/^[0-9a-fA-F]{6}$/.test(raw)){$('#colorStatus').textContent='Enter a six-digit HEX color, such as #7C5CFF.';return}const h='#'+raw.toUpperCase(),r=parseInt(raw.slice(0,2),16),g=parseInt(raw.slice(2,4),16),b=parseInt(raw.slice(4,6),16);$('#rgb').value='rgb('+r+', '+g+', '+b+')';$('#colorPreview').style.background=h;$('#colorPreview').textContent=h;$('#colorStatus').textContent='Converted successfully.'};
}
function uuid(){
 panel('<div id="uuidOut" class="result-box" aria-live="polite">Click generate.</div><div class="tool-actions"><button class="btn btn-primary" id="uuidBtn">Generate UUID</button><button class="btn btn-ghost" id="uuidCopy">Copy</button></div>');
 const out=$('#uuidOut');$('#uuidBtn').onclick=()=>{try{const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,v=>v.toString(16).padStart(2,'0')).join('');out.textContent=h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)}catch{out.textContent='Secure random number generation is unavailable in this browser.'}};$('#uuidCopy').onclick=async()=>{if(!out.textContent||out.textContent.includes('Click generate'))return;try{await navigator.clipboard.writeText(out.textContent)}catch{out.focus?.();toast('Clipboard unavailable; select and copy the UUID.')}}
}
function timer(){
 panel('<div class="timer-display" id="timerDisplay" role="timer" aria-live="polite">05:00</div><div class="form-grid"><div class="field"><label for="tm">Minutes</label><input id="tm" type="number" min="0" max="999" value="5"></div><div class="field"><label for="ts">Seconds</label><input id="ts" type="number" min="0" max="59" value="0"></div></div><div class="tool-actions"><button class="btn btn-primary" id="timerStart">Start</button><button class="btn btn-ghost" id="timerReset">Reset</button></div><p id="timerStatus" class="muted" role="status">Ready</p>');
 let iv=null,remain=300,hasConfig=false;const display=()=>{document.querySelector('#timerDisplay').textContent=String(Math.floor(remain/60)).padStart(2,'0')+':'+String(remain%60).padStart(2,'0')};const stop=()=>{clearInterval(iv);iv=null};const read=()=>{const m=Number($('#tm').value),s=Number($('#ts').value);if(!Number.isFinite(m)||!Number.isInteger(m)||m<0||m>999||!Number.isFinite(s)||!Number.isInteger(s)||s<0||s>59)throw Error('Enter valid whole minutes (0–999) and seconds (0–59).');const n=m*60+s;if(n<=0)throw Error('Set a duration greater than zero.');return n};activeToolCleanup=stop;display();
 $('#timerStart').onclick=()=>{if(iv){stop();$('#timerStart').textContent='Resume';$('#timerStatus').textContent='Paused';return}try{if(!hasConfig||remain<=0){remain=read();hasConfig=true;display()}}catch(e){$('#timerStatus').textContent=e.message;return}$('#timerStatus').textContent='Counting down';$('#timerStart').textContent='Pause';iv=setInterval(()=>{remain=Math.max(0,remain-1);display();if(remain===0){stop();hasConfig=false;$('#timerStart').textContent='Start again';$('#timerStatus').textContent='Time is up!';toast('Timer finished','good');window.JMBMusic?.notify?.()}},1000)};
 $('#timerReset').onclick=()=>{stop();try{remain=read();hasConfig=false;$('#timerStatus').textContent='Reset'}catch(e){remain=0;hasConfig=false;$('#timerStatus').textContent=e.message}display();$('#timerStart').textContent='Start'};
}
function stopwatch(){panel('<div class="timer-display" id="sw" role="timer">00:00.00</div><div class="tool-actions"><button class="btn btn-primary" id="swStart">Start</button><button class="btn btn-ghost" id="swReset">Reset</button></div>');let iv=null,start=0,elapsed=0;const out=document.querySelector('#sw'),btn=document.querySelector('#swStart');const draw=()=>{const ms=elapsed+(start?Date.now()-start:0),sec=Math.floor(ms/1000),hund=Math.floor(ms%1000/10);out.textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')+'.'+String(hund).padStart(2,'0')};const stop=()=>{if(start){elapsed+=Date.now()-start;start=0}clearInterval(iv);iv=null;draw()};activeToolCleanup=stop;btn.onclick=()=>{if(start){stop();btn.textContent='Resume';return}start=Date.now();iv=setInterval(draw,30);btn.textContent=elapsed?'Pause':'Pause'};document.querySelector('#swReset').onclick=()=>{stop();elapsed=0;draw();btn.textContent='Start'}} 
