async function encrypt(){
 panel('<p class="muted">AES-GCM authenticated encryption with a passphrase-derived key. Your text and passphrase stay in this browser; nothing is uploaded. Save the encrypted output and keep your passphrase separately.</p><label for="encPass">Passphrase (8+ characters)</label><input id="encPass" class="tool-input" type="password" autocomplete="off" minlength="8" placeholder="Enter a strong passphrase"><label for="encInput">Text to encrypt or encrypted package</label><textarea id="encInput" class="tool-area" placeholder="Type text to encrypt, or paste a JMBENC1 package to decrypt."></textarea><div class="tool-actions"><button class="btn btn-primary" id="encBtn">🔒 Encrypt text</button><button class="btn btn-ghost" id="decBtn">🔓 Decrypt package</button><button class="btn btn-ghost" id="encCopy">Copy output</button><button class="btn btn-ghost" id="encClear">Clear</button></div><label for="encOutput">Output</label><textarea id="encOutput" class="tool-area" readonly placeholder="Encrypted package or decrypted text will appear here."></textarea><div id="encStatus" class="muted" role="status">Uses AES-GCM with PBKDF2-SHA-256 and a fresh random salt and IV.</div>');
 const input=document.querySelector('#encInput'),pass=document.querySelector('#encPass'),output=document.querySelector('#encOutput'),status=document.querySelector('#encStatus');
 const enc=new TextEncoder(),dec=new TextDecoder();
 const to64=bytes=>{let bin='';for(let i=0;i<bytes.length;i+=0x8000)bin+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(bin)};
 const from64=s=>Uint8Array.from(atob(s),ch=>ch.charCodeAt(0));
 async function derive(password,salt,iterations){const material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
 function requireSecure(){if(!crypto?.subtle||!crypto?.getRandomValues)throw Error('Secure Web Crypto is unavailable. Open JMBHUB over HTTPS in a modern browser.')}
 document.querySelector('#encBtn').onclick=async()=>{const text=input.value,pw=pass.value,btn=document.querySelector('#encBtn');if(!text)return status.textContent='Enter text to encrypt.';if(pw.length<8)return status.textContent='Use a passphrase with at least 8 characters.';btn.disabled=true;status.textContent='Encrypting locally…';try{requireSecure();if(text.length>500000)throw Error('Maximum input size is 500,000 characters.');const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),iterations=250000,key=await derive(pw,salt,iterations),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(text)));const packageData={v:1,alg:'AES-GCM',kdf:'PBKDF2-SHA-256',iterations,salt:to64(salt),iv:to64(iv),data:to64(cipher)};output.value='JMBENC1.'+to64(enc.encode(JSON.stringify(packageData)));status.textContent='Encrypted successfully. Copy or save the JMBENC1 package; without the passphrase it cannot be decrypted.';window.JMBMusic?.win?.()}catch(e){status.textContent=e?.message||'Encryption failed.'}finally{btn.disabled=false}};
 document.querySelector('#decBtn').onclick=async()=>{const pw=pass.value,raw=input.value.trim(),btn=document.querySelector('#decBtn');if(pw.length<8)return status.textContent='Enter the same passphrase (8+ characters) used to encrypt.';if(!raw.startsWith('JMBENC1.'))return status.textContent='This is not a JMBENC1 encrypted package.';btn.disabled=true;status.textContent='Decrypting locally…';try{requireSecure();const packageData=JSON.parse(dec.decode(from64(raw.slice(8))));if(packageData.v!==1||packageData.alg!=='AES-GCM'||packageData.kdf!=='PBKDF2-SHA-256'||!Number.isInteger(packageData.iterations)||packageData.iterations<100000||packageData.iterations>1000000)throw Error('Unsupported or invalid encrypted package.');const salt=from64(packageData.salt),iv=from64(packageData.iv),cipher=from64(packageData.data);if(salt.length!==16||iv.length!==12||cipher.length>600000)throw Error('Invalid encrypted package data.');const key=await derive(pw,salt,packageData.iterations),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,cipher);output.value=dec.decode(plain);status.textContent='Decrypted successfully. The text is displayed only in this browser.';window.JMBMusic?.win?.()}catch(e){output.value='';status.textContent='Could not decrypt. Check the passphrase and ensure the package is complete.'}finally{btn.disabled=false}};
 document.querySelector('#encCopy').onclick=async()=>{if(!output.value)return status.textContent='There is no output to copy.';try{await navigator.clipboard.writeText(output.value);status.textContent='Output copied.'}catch{output.focus();output.select();status.textContent='Clipboard access is blocked. Select the output and copy it manually.'}};
 document.querySelector('#encClear').onclick=()=>{input.value='';output.value='';pass.value='';status.textContent='Cleared. Nothing was uploaded.'};
}

function markdown(){panel('<textarea id="mdIn" class="tool-area" placeholder="# Hello JMB"></textarea><div id="mdOut" class="result-box" style="display:block;min-height:180px"></div>');$('#mdIn').oninput=()=>{let s=$('#mdIn').value.replace(/[&<>]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[x]));s=s.replace(/^### (.*)$/gm,'<h4>$1</h4>').replace(/^## (.*)$/gm,'<h3>$1</h3>').replace(/^# (.*)$/gm,'<h2>$1</h2>').replace(/\*\*(.*?)\*\*/g,'<b>$1</b>').replace(/\*(.*?)\*/g,'<i>$1</i>').replace(/\n/g,'<br>');$('#mdOut').innerHTML=s}}
function timestamp(){
 panel('<div class="form-grid"><div class="field"><label for="dateIn">Local date/time</label><input id="dateIn" type="datetime-local"></div><div class="field"><label for="unixIn">Unix timestamp (seconds)</label><input id="unixIn" type="number" step="any" placeholder="e.g. 1735689600"></div></div><div id="timeOut" class="result-box" aria-live="polite">—</div><div class="tool-actions"><button class="btn btn-primary" id="timeNow">Convert</button><button class="btn btn-ghost" id="timeCurrent">Use current time</button></div>');
 $('#timeNow').onclick=()=>{const dateVal=$('#dateIn').value,unixVal=$('#unixIn').value.trim();if(dateVal&&unixVal){$('#timeOut').textContent='Fill either the date/time or Unix timestamp, not both.';return}if(dateVal){const ms=new Date(dateVal).getTime();$('#timeOut').textContent=Number.isFinite(ms)?'Unix seconds: '+Math.floor(ms/1000)+' · Unix milliseconds: '+ms:'Invalid date'}else if(unixVal!==''){const n=Number(unixVal),ms=n*1000;if(!Number.isFinite(n)||!Number.isFinite(ms)||Math.abs(ms)>8640000000000000){$('#timeOut').textContent='Enter a valid Unix timestamp.';return}const d=new Date(ms);$('#timeOut').textContent=d.toLocaleString()+' ('+d.toISOString()+')'}else $('#timeOut').textContent='Enter a date/time or Unix timestamp.'};
 $('#timeCurrent').onclick=()=>{const now=new Date(),local=new Date(now.getTime()-now.getTimezoneOffset()*60000);$('#dateIn').value=local.toISOString().slice(0,16);$('#unixIn').value='';$('#timeNow').click()};
}
function password(){
 panel('<div class="form-grid"><div class="field"><label for="pwLen">Length (8–64)</label><input id="pwLen" type="number" min="8" max="64" step="1" value="16"></div><div class="field"><label for="pwOut">Generated password</label><input id="pwOut" class="tool-input" readonly autocomplete="off"></div></div><div class="tool-actions"><button class="btn btn-primary" id="pwBtn">Generate secure password</button><button class="btn btn-ghost" id="pwCopy">Copy password</button></div><p class="muted">Generated locally using the browser cryptographic random-number generator. JMBHUB never receives or saves it.</p><div id="pwStatus" class="muted" role="status"></div>');
 const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%^&*_-+=';$('#pwBtn').onclick=()=>{const n=Number($('#pwLen').value);if(!Number.isInteger(n)||n<8||n>64){$('#pwStatus').textContent='Choose a whole-number length from 8 to 64.';return}try{const limit=Math.floor(256/chars.length)*chars.length,bytes=new Uint8Array(n*4);let result='';while(result.length<n){crypto.getRandomValues(bytes);for(const b of bytes){if(b<limit)result+=chars[b%chars.length];if(result.length===n)break}}$('#pwOut').value=result;$('#pwStatus').textContent='Password created. Store it in a trusted password manager.'}catch{$('#pwStatus').textContent='Secure random number generation is unavailable.'}};$('#pwCopy').onclick=async()=>{if(!$('#pwOut').value){$('#pwStatus').textContent='Generate a password first.';return}try{await navigator.clipboard.writeText($('#pwOut').value);$('#pwStatus').textContent='Copied to clipboard.'}catch{$('#pwOut').focus();$('#pwOut').select();$('#pwStatus').textContent='Clipboard blocked; selected the password so you can copy it manually.'}}
}
function regex(){
 panel('<label for="rx">Regular expression</label><input id="rx" class="tool-input" maxlength="250" placeholder="Example: ^JMB"><label for="rxText">Text to test (maximum 10,000 characters)</label><textarea id="rxText" class="tool-area" maxlength="10000" placeholder="Text to test"></textarea><div id="rxOut" class="result-box" role="status">—</div><button class="btn btn-primary" id="rxBtn">Test pattern</button><p class="muted">The pattern runs in a short-lived worker so a slow expression can be stopped without blocking the whole page.</p>');
 const btn=$('#rxBtn'),out=$('#rxOut');let worker=null,timer=null,blobUrl=null;
 const cleanup=()=>{if(timer!==null){clearTimeout(timer);timer=null}if(worker){worker.terminate();worker=null}if(blobUrl){URL.revokeObjectURL(blobUrl);blobUrl=null}btn.disabled=false};
 activeToolCleanup=cleanup;
 btn.onclick=()=>{cleanup();const pattern=$('#rx').value,text=$('#rxText').value;if(!pattern){out.textContent='Enter a regular expression.';return}if(pattern.length>250||text.length>10000){out.textContent='Pattern or test text is too long.';return}
 try{const source="onmessage=e=>{try{const re=new RegExp(e.data.pattern);const m=re.exec(e.data.text);postMessage({ok:true,match:!!m,value:m?m[0]:''})}catch(e){postMessage({ok:false,error:'Invalid regular expression.'})}}";blobUrl=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));worker=new Worker(blobUrl);btn.disabled=true;out.textContent='Testing…';worker.onmessage=e=>{const d=e.data||{};if(timer!==null){clearTimeout(timer);timer=null}worker?.terminate();worker=null;if(blobUrl){URL.revokeObjectURL(blobUrl);blobUrl=null}btn.disabled=false;out.textContent=d.ok?(d.match?'Match found: '+d.value:'No match'):d.error||'Pattern test failed.'};worker.onerror=()=>{cleanup();out.textContent='Pattern worker failed. Try a simpler expression.'};worker.postMessage({pattern,text});timer=setTimeout(()=>{cleanup();out.textContent='This pattern took too long. Try a simpler expression.'},600)}catch{cleanup();out.textContent='This browser could not start a pattern worker.'}
 }
}
function gradient(){panel('<div class="form-grid"><div class="field"><label>Start</label><input id="g1" value="#7c5cff"></div><div class="field"><label>End</label><input id="g2" value="#00c6ea"></div></div><div id="gradOut" class="result-box" style="height:150px"></div><div class="tool-actions"><button class="btn btn-primary" id="gradBtn">Build</button><button class="btn btn-ghost" id="gradCopy">Copy CSS</button></div>');const draw=()=>{const v='linear-gradient(135deg,'+$('#g1').value+','+$('#g2').value+')';$('#gradOut').style.background=v;$('#gradOut').dataset.css='background:'+v+';'};$('#gradBtn').onclick=draw;$('#gradCopy').onclick=()=>navigator.clipboard?.writeText($('#gradOut').dataset.css||'');draw()}
function csv(){
 panel('<p class="muted">Supports quoted fields, commas inside quotes and escaped double quotes. The table is rendered as text, not executable HTML.</p><textarea id="csvIn" class="tool-area" placeholder="name,score\nJMB,100"></textarea><div id="csvStatus" class="muted" role="status"></div><div class="table-wrap"><table class="table"><tbody id="csvOut"></tbody></table></div><button class="btn btn-primary" id="csvBtn">Render CSV</button>');
 const escape=v=>String(v??'').replace(/[&<>"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]));
 function parse(input){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<input.length;i++){const ch=input[i];if(ch==='"'){if(quoted&&input[i+1]==='"'){cell+='"';i++}else if(quoted)quoted=false;else if(cell==='')quoted=true;else cell+='"'}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&input[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell=''}else cell+=ch}if(quoted)throw Error('A quoted field is not closed.');if(cell!==''||row.length){row.push(cell);rows.push(row)}return rows}
 $('#csvBtn').onclick=()=>{try{const input=$('#csvIn').value;if(input.length>200000)throw Error('Please keep CSV under 200,000 characters.');const rows=parse(input);if(!rows.length)throw Error('Paste CSV content first.');if(rows.length>500||Math.max(...rows.map(r=>r.length))>50)throw Error('Limit: 500 rows and 50 columns.');$('#csvOut').innerHTML=rows.map((r,i)=>'<tr>'+r.map(v=>'<'+(i===0?'th':'td')+'>'+escape(v)+'</'+(i===0?'th':'td')+'>').join('')+'</tr>').join('');$('#csvStatus').textContent=rows.length+' rows • '+Math.max(...rows.map(r=>r.length))+' columns'}catch(e){$('#csvOut').innerHTML='';$('#csvStatus').textContent=e.message||'Could not parse CSV.'}};
}
