function jwt(){
 panel('<p class="muted">Decodes the readable header and payload only. This does not verify the JWT signature or prove that the token is authentic. Avoid pasting production access tokens into shared devices.</p><textarea id="jwtIn" class="tool-area" autocomplete="off" placeholder="Paste a three-part JWT"></textarea><div id="jwtOut" class="result-box" style="display:block;white-space:pre-wrap;word-break:break-word" aria-live="polite"></div><button class="btn btn-primary" id="jwtBtn">Decode token</button>');
 $('#jwtBtn').onclick=()=>{try{const parts=$('#jwtIn').value.trim().split('.');if(parts.length!==3)throw Error('A JWT must contain three dot-separated parts.');const decPart=s=>{const b64=s.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(s.length/4)*4,'=');const bytes=Uint8Array.from(atob(b64),ch=>ch.charCodeAt(0));return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes))};const header=decPart(parts[0]),payload=decPart(parts[1]);$('#jwtOut').textContent=JSON.stringify({header,payload,signaturePresent:parts[2].length>0},null,2)+'\n\n⚠️ Signature not verified.'}catch(e){$('#jwtOut').textContent=e?.message||'Invalid JWT'}}}
function diff(){
 panel('<div class="form-grid"><div class="field"><label for="diffA">Original text</label><textarea id="diffA" class="tool-area" placeholder="Original text"></textarea></div><div class="field"><label for="diffB">New text</label><textarea id="diffB" class="tool-area" placeholder="Updated text"></textarea></div></div><div id="diffOut" class="result-box" style="display:block;white-space:pre-wrap;word-break:break-word" aria-live="polite">Compare two texts to see changed lines.</div><button class="btn btn-primary" id="diffBtn">Compare</button>');
 $('#diffBtn').onclick=()=>{const a=$('#diffA').value.split(/\n/),b=$('#diffB').value.split(/\n/);if(a.length>5000||b.length>5000){$('#diffOut').textContent='Each text is limited to 5,000 lines.';return}const out=[];for(let i=0;i<Math.max(a.length,b.length);i++){if(a[i]===b[i])continue;if(a[i]!==undefined)out.push('- Line '+(i+1)+': '+a[i]);if(b[i]!==undefined)out.push('+ Line '+(i+1)+': '+b[i])}$('#diffOut').textContent=out.join('\n')||'No differences'};
}
function baseconv(){
 panel('<div class="form-grid"><div class="field"><label for="bcIn">Integer</label><input id="bcIn" class="tool-input" value="255" inputmode="text" placeholder="Enter digits without prefixes"></div><div class="field"><label for="bcBase">Input base</label><select id="bcBase" class="tool-input"><option value="10">Decimal (10)</option><option value="2">Binary (2)</option><option value="8">Octal (8)</option><option value="16">Hexadecimal (16)</option></select></div></div><div id="bcOut" class="result-box" aria-live="polite">Decimal: 255 | Binary: 11111111 | Octal: 377 | Hex: FF</div><button class="btn btn-primary" id="bcBtn">Convert</button>');
 $('#bcBtn').onclick=()=>{const raw=$('#bcIn').value.trim().replaceAll('_',''),base=Number($('#bcBase').value),digits='0123456789abcdef';if(!raw){$('#bcOut').textContent='Enter an integer first.';return}const negative=raw.startsWith('-'),input=negative?raw.slice(1):raw;if(!input){$('#bcOut').textContent='Invalid integer.';return}let n=0n;try{for(const ch of input.toLowerCase()){const digit=digits.indexOf(ch);if(digit<0||digit>=base){$('#bcOut').textContent='Invalid digit for base '+base+'.';return}n=n*BigInt(base)+BigInt(digit)}if(negative)n=-n;$('#bcOut').textContent='Decimal: '+n.toString(10)+' | Binary: '+n.toString(2)+' | Octal: '+n.toString(8)+' | Hex: '+n.toString(16).toUpperCase()}catch{$('#bcOut').textContent='Invalid integer.'}};
}
