function datecalc(){
 panel('<p class="muted">Calculate the calendar-day and elapsed-time difference between two dates.</p><div class="form-grid"><div class="field"><label for="dateStart">Start date and time</label><input id="dateStart" type="datetime-local" class="tool-input"></div><div class="field"><label for="dateEnd">End date and time</label><input id="dateEnd" type="datetime-local" class="tool-input"></div></div><div class="tool-actions"><button class="btn btn-primary" id="dateDiffBtn">Calculate difference</button><button class="btn btn-ghost" id="dateDiffReset">Reset</button></div><div id="dateDiffOutput" class="result-box" style="display:block;white-space:pre-wrap">Choose two dates to begin.</div><p id="dateDiffStatus" class="muted" role="status"></p>');
 const start=$('#dateStart'),end=$('#dateEnd'),out=$('#dateDiffOutput'),status=$('#dateDiffStatus');
 $('#dateDiffBtn').onclick=()=>{const a=new Date(start.value),b=new Date(end.value);if(!start.value||!end.value||!Number.isFinite(a.getTime())||!Number.isFinite(b.getTime())){status.textContent='Choose both dates and times.';return}const ms=Math.abs(b-a),days=Math.floor(ms/86400000),hours=Math.floor(ms%86400000/3600000),minutes=Math.floor(ms%3600000/60000);out.textContent='Elapsed time: '+days+' days, '+hours+' hours, '+minutes+' minutes\nTotal hours: '+(ms/3600000).toFixed(2)+'\nDirection: '+(b>=a?'End is after start':'End is before start');status.textContent='Difference calculated.'};
 $('#dateDiffReset').onclick=()=>{start.value='';end.value='';out.textContent='Choose two dates to begin.';status.textContent=''};
}
function ip(){panel('<div class="notice">This tool does not look up or send your public IP address. It only reads information already exposed to this browser.</div><div id="ipOut" class="result-box" style="display:block;word-break:break-word">Checking…</div><button class="btn btn-ghost" id="ipRefresh">Refresh</button>');const draw=()=>{$('#ipOut').textContent='Browser: '+navigator.userAgent+'\nOnline status: '+(navigator.onLine?'Online':'Offline')+'\nLanguage: '+(navigator.language||'Unknown')+'\nPlatform: '+(navigator.platform||'Not provided by browser')};$('#ipRefresh').onclick=draw;draw()}
await guard();render();document.querySelector('#toolSearch')?.addEventListener('input',e=>render(e.target.value));
